/** Generated by vite-plugin-sizes.ts from the size-limit report (#9). */
declare module "virtual:menhir-sizes" {
  export type EntryPointSize = {
    /** Such as "menhir/switch". */
    entryPoint: string;
    /** Measured size in bytes, minified and gzipped, Solid left out. */
    size: number;
  };

  /** One row per entry point of menhir. Empty when the report is missing. */
  export const sizes: readonly EntryPointSize[];
}

/**
 * `virtual:menhir-sizes/switch` is the measured size of `menhir/switch` in
 * bytes. The build fails if the report does not have the entry point; in dev
 * and tests it is undefined.
 */
declare module "virtual:menhir-sizes/*" {
  const size: number | undefined;
  export default size;
}

/**
 * Generated by vite-plugin-sizes.ts from test/bundle-size/dist/comparison.json:
 * other libraries' versions of menhir's components, measured as menhir's
 * entry points are, with each library's framework left out.
 */
declare module "virtual:size-comparison" {
  export type ComparedComponent = {
    /** Such as "@radix-ui/react-switch". */
    module: string;
    /** The version of the module's package that was measured. */
    version: string;
    /** Measured size in bytes, minified and gzipped, the framework left out. */
    size: number;
  };

  export type ComparedLibrary = {
    /** Such as "Radix". */
    name: string;
    /** Such as "React". */
    framework: string;
    /**
     * By the subpath of menhir's entry point, such as "switch". A component
     * the library does not have is left out.
     */
    components: Readonly<Record<string, ComparedComponent>>;
  };

  /** Empty when the report is missing. */
  export const libraries: readonly ComparedLibrary[];
}
